export type Level = 'Beginner' | 'Foundation' | 'Mid-level' | 'Senior';

export interface Mission {
  id: string;
  title: string;
  level: Level;
  theme: string;
  minutes: number;
  summary: string;
  prerequisites: string[];
  outcomes: string[];
  concepts: { title: string; body: string }[];
  codeRefs: { path: string; reason: string }[];
  lab: { title: string; steps: string[]; deliverable: string };
  checkpoints: { question: string; answer: string }[];
  rubric: string[];
  stretch: string;
  resources: { label: string; href: string }[];
}

export const levels: Level[] = ['Beginner', 'Foundation', 'Mid-level', 'Senior'];

