    lab: { title: 'Catch a deliberate regression', steps: ['Choose a grade or coursework rule and identify one behavior whose failure would hurt a user.', 'Add an independently calculated boundary or invariant test.', 'Temporarily change the relevant comparison or state transition in a practice branch and show that the new test fails; restore the rule.', 'Run npm test and document one important behavior that still requires integration or manual verification.'], deliverable: 'A focused regression test with the observed failing and passing result, plus a coverage limitation.' },
    checkpoints: [{ question: 'Why can a passing snapshot test miss a policy error?', answer: 'A snapshot may simply preserve an incorrect output. A reviewed policy example supplies a meaningful expected result.' }, { question: 'What does an enrollment unit test leave unproven?', answer: 'It does not establish atomic database updates, authorization, or behavior under concurrent requests.' }],
    rubric: ['Uses an independently justified expected result.', 'Shows the test fails for the intended regression.', 'Explains one boundary between unit and integration evidence.'],
